package com.nexus.service; import com.nexus.domain.*; import com.nexus.domain.Rules.Role; import com.nexus.data.AccountRepository; import com.nexus.web.ApiErrors.Missing; import org.springframework.stereotype.Service; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.*;
@Service public class Accounts{public final AccountRepository repo;private final PasswordEncoder encoder;public Accounts(AccountRepository r,PasswordEncoder e){repo=r;encoder=e;}public String normalize(String e){return e.trim().toLowerCase(Locale.ROOT);}public Account current(String email){Account a=repo.findByEmail(email).orElseThrow(()->new AccessDeniedException("Unknown account"));if(!a.enabled)throw new AccessDeniedException("Disabled account");return a;}public Account get(long id){return repo.findById(id).orElseThrow(()->new Missing("User not found"));}public Account register(String n,String e,String p,Role r){String email=normalize(e);if(repo.findByEmail(email).isPresent())throw new IllegalArgumentException("Email already registered");if(p.length()<10||p.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new IllegalArgumentException("Password must be 10–72 UTF-8 bytes");String h=encoder.encode(p);return repo.save(switch(r){case EMPLOYEE->new Employee(n.trim(),email,h);case TECHNICIAN->new Technician(n.trim(),email,h);case ADMINISTRATOR->new Administrator(n.trim(),email,h);});}public boolean matches(String raw,Account a){return a.enabled&&encoder.matches(raw,a.passwordHash);}public void require(Account a,Role role){if(a.role()!=role)throw new AccessDeniedException("Role required");}}
